"""Write the held-out calibration report.

From services/ml:

    python scripts/evaluate_calibration.py

The script does not load the forest and does not call EasyOCR.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

SERVICE_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(SERVICE_ROOT))

from app.calibration import evaluate_held_out


def render(report: dict) -> str:
    lines = [
        "# Calibration report",
        "",
        "Generated by `services/ml/scripts/evaluate_calibration.py`.",
        "The published forest was not loaded. EasyOCR was not called.",
        "",
        f"Status: **{report['status']}**.",
        f"Labeled calibration rows: {report['rows']}.",
        f"`probabilitiesCalibrated`: {str(report['probabilitiesCalibrated']).lower()}.",
        "",
        "## Why no map is installed",
        "",
        report["fit"]["reason"],
        "",
        "## Metrics",
        "",
    ]
    for name in ("ece", "brier", "nll", "coverageRisk"):
        value = report[name]
        if isinstance(value, dict) and value.get("status") == "unavailable":
            lines.append(f"- {name}: unavailable. {value['reason']}")
        elif isinstance(value, dict) and value.get("status") == "computed":
            lines.append(f"- {name}: computed on {value.get('rows', report['rows'])} rows.")
        else:
            lines.append(f"- {name}: {json.dumps(value, ensure_ascii=False)}")
    lines.extend([
        "",
        "## Methods that were not applied",
        "",
        f"- Temperature scaling: {report['temperatureScaling']['reason']}",
        f"- OCR box scores: {report['ocrScores']['reason']}",
        "",
        "Vote shares and box scores stay labeled uncalibrated in the API.",
        "",
    ])
    return "\n".join(lines)


def main() -> None:
    report = evaluate_held_out()
    json_path = SERVICE_ROOT / "calibration" / "calibration-report.json"
    markdown_path = SERVICE_ROOT.parents[1] / "docs" / "evaluation" / "CALIBRATION_REPORT.md"
    markdown_path.parent.mkdir(parents=True, exist_ok=True)
    json_path.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
    markdown_path.write_text(render(report), encoding="utf-8")
    print(json.dumps({
        "status": report["status"],
        "rows": report["rows"],
        "probabilitiesCalibrated": report["probabilitiesCalibrated"],
        "markdown": str(markdown_path),
    }, indent=2))


if __name__ == "__main__":
    main()
